using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using System.Reflection;
public static class BeachForestV2 {
 static BindingFlags flags=BindingFlags.Static|BindingFlags.NonPublic;
 static object Call(string n,params object[] a)=>typeof(ArtLibraryBuilder).GetMethod(n,flags).Invoke(null,a);
 static Vector2[][] routes={new[]{new Vector2(-65,-65),new Vector2(-25,-65),new Vector2(15,-35),new Vector2(5,0),new Vector2(45,35),new Vector2(22,75),new Vector2(60,115)},new[]{new Vector2(-25,-65),new Vector2(-65,-35),new Vector2(-105,-20)},new[]{new Vector2(45,35),new Vector2(90,50),new Vector2(110,80)}};
 static float Dist(float x,float z){float d=999;var p=new Vector2(x,z);foreach(var r in routes)for(int i=1;i<r.Length;i++){var v=r[i]-r[i-1];d=Mathf.Min(d,Vector2.Distance(p,r[i-1]+v*Mathf.Clamp01(Vector2.Dot(p-r[i-1],v)/v.sqrMagnitude)));}return d;}
 static float H(float x,float z){float radius=Mathf.Sqrt(x*x/(205*205)+z*z/(215*215));float coast=-78+22*Mathf.Cos(x*.021f)+9*Mathf.Sin(x*.048f);float shore=(z-coast)*.13f;float hills=5+Mathf.PerlinNoise(x*.012f+10,z*.012f+10)*15;float h=Mathf.Min(shore,hills);h+=Mathf.SmoothStep(0,1,Mathf.InverseLerp(115,190,z))*35;h=Mathf.Lerp(h,-12,Mathf.SmoothStep(0,1,Mathf.InverseLerp(.77f,1.04f,radius)));return Mathf.Max(-15,h);}
 [MenuItem("Art/Rebuild Beach Forest V2")]
 public static void Build(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);UnityEngine.Random.InitState(821);AssetDatabase.DeleteAsset("Assets/ArtPreview/V2Fixed");Directory.CreateDirectory("Assets/ArtPreview/V2Fixed");
 var data=new TerrainData{heightmapResolution=513,size=new Vector3(460,90,460),alphamapResolution=512};var heights=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++)heights[z,x]=(H(x/512f*460-230,z/512f*460-230)+20)/90;data.SetHeights(0,0,heights);
 var colors=new[]{new Color(.86f,.74f,.48f),new Color(.32f,.46f,.19f),new Color(.52f,.39f,.23f)};var layers=new TerrainLayer[3];for(int i=0;i<3;i++){var t=new Texture2D(4,4);t.SetPixels(Enumerable.Repeat(colors[i],16).ToArray());t.Apply();AssetDatabase.CreateAsset(t,"Assets/ArtPreview/V2Fixed/Color"+i+".asset");layers[i]=new TerrainLayer{diffuseTexture=t,tileSize=new Vector2(12,12)};AssetDatabase.CreateAsset(layers[i],"Assets/ArtPreview/V2Fixed/Layer"+i+".asset");}data.terrainLayers=layers;var alpha=new float[512,512,3];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float xx=x/511f*460-230,zz=z/511f*460-230;float grass=Mathf.SmoothStep(0,1,Mathf.InverseLerp(-35,-4,zz+12*Mathf.Sin(xx*.043f)));float path=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.3f,4.5f,Dist(xx,zz))))*grass;alpha[z,x,0]=1-grass;alpha[z,x,1]=grass-path;alpha[z,x,2]=path;}data.SetAlphamaps(0,0,alpha);AssetDatabase.CreateAsset(data,"Assets/ArtPreview/V2Fixed/IslandTerrain.asset");var terrain=Terrain.CreateTerrainGameObject(data);terrain.name="V2 continuous sculpted island";terrain.transform.position=new Vector3(-230,-20,-230);
 Call("Ground","Open sea",new Vector3(0,0,0),new Vector3(180,1,180),Call("Mat","V2 sea",new Color(.12f,.58f,.67f)));
 var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Art/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).ToArray();var trees=paths.Where(p=>p.Contains("CommonTree")).ToArray();var palms=paths.Where(p=>p.Contains("palm-")).ToArray();var rocks=paths.Where(p=>p.Contains("Rock_Medium")).ToArray();var bushes=paths.Where(p=>p.Contains("Bush_")).ToArray();
 Action<string,float,float,float> place=(p,x,z,h)=>{if(p==null)return;var g=(GameObject)Call("Spawn",p,new Vector3(x,H(x,z)-.12f,z),h,UnityEngine.Random.Range(0f,360f));if(h>3&&g){var b=new Bounds();bool first=true;foreach(var rr in g.GetComponentsInChildren<Renderer>()){if(first){b=rr.bounds;first=false;}else b.Encapsulate(rr.bounds);}var col=g.AddComponent<CapsuleCollider>();col.center=g.transform.InverseTransformPoint(new Vector3(b.center.x,b.min.y+1.7f,b.center.z));col.radius=.35f/g.transform.lossyScale.x;col.height=3.4f/g.transform.lossyScale.y;}};
 var positions=new System.Collections.Generic.List<Vector2>();for(int i=0;i<2200;i++){float x=UnityEngine.Random.Range(-180,180),z=UnityEngine.Random.Range(-95,175);if(H(x,z)<1||Dist(x,z)<6||Vector2.Distance(new Vector2(x,z),new Vector2(60,115))<15||Vector2.Distance(new Vector2(x,z),new Vector2(110,80))<12)continue;if(positions.Any(p=>Vector2.Distance(p,new Vector2(x,z))<8))continue;positions.Add(new Vector2(x,z));var pool=z< -15?palms:trees;if(pool.Length>0)place(pool[i%pool.Length],x,z,UnityEngine.Random.Range(7f,13f));}
 for(int i=0;i<700;i++){float x=UnityEngine.Random.Range(-170,170),z=UnityEngine.Random.Range(-95,175);if(H(x,z)<.3f||Dist(x,z)<5)continue;var pool=i%3==0?rocks:bushes;if(pool.Length>0)place(pool[i%pool.Length],x,z,i%3==0?UnityEngine.Random.Range(1f,5f):UnityEngine.Random.Range(.5f,1.6f));}
 place(paths.FirstOrDefault(p=>p.Contains("ship-")),-72,-78,6);place(paths.FirstOrDefault(p=>p.Contains("boat-row-small")),-52,-73,1);for(int i=0;i<12;i++)place(paths.FirstOrDefault(p=>p.Contains(i%2==0?"crate":"plank")),-69+i*1.7f,-67+Mathf.Sin(i)*4,i%2==0?.7f:.15f);
 var c=(Camera)Call("Lighting",new Vector3(-65,H(-65,-65)+2.5f,-71),new Vector3(-25,7,-65));c.farClipPlane=1800;var views=new[]{new Vector2(-65,-65),new Vector2(15,-35),new Vector2(5,0),new Vector2(60,115)};for(int i=0;i<views.Length;i++){var p=views[i];c.transform.position=new Vector3(p.x,H(p.x,p.y)+2.5f,p.y-5);c.transform.LookAt(new Vector3(p.x+7,H(p.x,p.y)+1.5f,p.y+15));Call("Shot",c,"V2_View_"+i,1600,1000);}c.transform.position=new Vector3(280,330,-350);c.transform.LookAt(new Vector3(0,0,30));Call("Shot",c,"V2_Overview",1600,1000);c.transform.position=new Vector3(-65,H(-65,-65)+2.5f,-71);c.transform.LookAt(new Vector3(-25,7,-65));EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),"Assets/Scenes/ArtTest/BeachForest_ArtTest.unity");AssetDatabase.SaveAssets();Debug.Log("BEACH_FOREST_V2_BUILT");}
}


